func calculateTokenUsage(agentType types.AgentType, data []byte, offset int) *agent.TokenUsage {
	ag, err := agent.GetByAgentType(agentType)
	if err != nil {
		return nil
	}
	return agent.CalculateTokenUsage(context.Background(), ag, data, offset, "")
